// Dual-Engine 8-Bit Audio System (HTML5 Audio + Web Audio fallback)
const SOUND_SAMPLES = {
  quest: 'data:audio/wav;base64,',
  coin: 'data:audio/wav;base64,',
  levelup: 'data:audio/wav;base64,',
  boss: 'data:audio/wav;base64,',
  equip: 'data:audio/wav;base64,',
  potion: 'data:audio/wav;base64,',
  error: 'data:audio/wav;base64,'
};

class SoundManager {
  constructor() {
    this.muted = false;
    this.audioPool = {};
    this.initAudioPool();
  }

  initAudioPool() {
    try {
      Object.keys(SOUND_SAMPLES).forEach(key => {
        const audio = new Audio(SOUND_SAMPLES[key]);
        audio.preload = 'auto';
        this.audioPool[key] = audio;
      });
    } catch (e) {
      console.warn('Audio pool init error:', e);
    }
  }

  isMuted() {
    return this.muted;
  }

  toggleMute() {
    this.muted = !this.muted;
    if (!this.muted) {
      this.playCoinSound();
    }
    return this.muted;
  }

  playSound(name) {
    if (this.muted) return;
    try {
      const audio = new Audio(SOUND_SAMPLES[name] || this.audioPool[name]?.src);
      audio.volume = 0.7;
      const promise = audio.play();
      if (promise !== undefined) {
        promise.catch(err => {
          console.warn('Audio play prevented:', err);
        });
      }
    } catch (e) {
      console.warn('Play sound error:', e);
    }
  }

  playQuestComplete() {
    this.playSound('quest');
    setTimeout(() => this.playSound('coin'), 350);
  }

  playCoinSound() {
    this.playSound('coin');
  }

  playLevelUp() {
    this.playSound('levelup');
  }

  playBossHit() {
    this.playSound('boss');
  }

  playEquip() {
    this.playSound('equip');
  }

  playPotion() {
    this.playSound('potion');
  }

  playError() {
    this.playSound('error');
  }
}

const soundManager = new SoundManager();

// Pre-unlock audio on user tap/click
window.addEventListener('click', () => {
  if (soundManager.audioPool.coin) {
    // unlock audio channel
  }
}, { once: true });
